UPDATE `MonsterInfo` SET `Enhance` = '(HP,18)(TOHIT,-35)(DEFENSE,-60)(MINDAMAGE,-29)(MAXDAMAGE,-29)(DECREASEDAMAGE,0)', `ADelay` = 1200 WHERE `MType` = 821 AND `Enhance` IN ('(HP,184)(TOHIT,7)(DEFENSE,-60)(MINDAMAGE,35)(MAXDAMAGE,35)(DECREASEDAMAGE,15)', '(HP,18)(TOHIT,-35)(DEFENSE,-60)(MINDAMAGE,-29)(MAXDAMAGE,-29)(DECREASEDAMAGE,0)') AND `ADelay` IN (775, 1200);
